static pthread_t           thread;
static int                 listen_fd = -1;
static bool                started;
static volatile int        stopping;
static char                auth_token[320];   /* "Basic <base64(user:pass)>" */

/* ------------------------------------------------------------------ */
/* HTTP helpers                                                        */
/* ------------------------------------------------------------------ */

static void send_all(int fd, const void *data, size_t len)
{
	const char *p = data;

	while (len > 0) {
		ssize_t n = send(fd, p, len, MSG_NOSIGNAL);   /* no SIGPIPE */
		if (n < 0 && errno == EINTR)
			continue;
		if (n <= 0)
			return;
		p   += n;
		len -= (size_t)n;
	}
}

static void respond(int fd, int code, const char *reason, const char *type,
                    const void *body, size_t len, const char *extra_headers)
{
	char head[384];
	int  n = snprintf(head, sizeof head,
		"HTTP/1.1 %d %s\r\n"
		"Content-Type: %s\r\n"
		"Content-Length: %zu\r\n"
		"Cache-Control: no-store\r\n"
		"Connection: close\r\n"
		"%s\r\n",
		code, reason, type, len, extra_headers);

	send_all(fd, head, (size_t)n);
	send_all(fd, body, len);
}

static void respond_text(int fd, int code, const char *reason)
{
	respond(fd, code, reason, "text/plain", reason, strlen(reason), "");
}

/* Returns a pointer to the value of a request header, or NULL. */
static const char *header(const char *req, const char *name)
{
	size_t len = strlen(name);

	for (const char *line = strstr(req, "\r\n"); line; line = strstr(line + 2, "\r\n")) {
		const char *h = line + 2;
		if (h[0] == '\r' || h[0] == '\0')
			break;   /* end of headers: never match text in the body */
		if (strncasecmp(h, name, len) == 0 && h[len] == ':') {
			h += len + 1;
			while (*h == ' ')
				h++;
			return h;
		}
	}
	return NULL;
}

/* ------------------------------------------------------------------ */
/* Basic auth (browser shows the login prompt, resends it on /api/)    */
/* ------------------------------------------------------------------ */

static void base64(const unsigned char *in, size_t len, char *out)
{
	static const char t[] =
		"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

	while (len > 0) {
		unsigned v = (unsigned)in[0] << 16
		           | (len > 1 ? (unsigned)in[1] << 8 : 0)
		           | (len > 2 ? in[2] : 0);

		*out++ = t[v >> 18 & 63];
		*out++ = t[v >> 12 & 63];
		*out++ = len > 1 ? t[v >> 6 & 63] : '=';
		*out++ = len > 2 ? t[v & 63]      : '=';

		size_t used = len > 3 ? 3 : len;
		in  += used;
		len -= used;
	}
	*out = '\0';
}

static bool authorized(const char *req)
{
	const char *v = header(req, "Authorization");
	if (!v)
		return false;

	size_t have = strcspn(v, "\r\n");
	size_t want = strlen(auth_token);

	unsigned diff = (have != want);
	for (size_t i = 0; i < want; i++)   /* compare everything, no early exit */
		diff |= (unsigned char)(i < have ? v[i] : 0) ^ (unsigned char)auth_token[i];

	return diff == 0;
}

/* ------------------------------------------------------------------ */
/* JSON builder                                                        */
/* ------------------------------------------------------------------ */

typedef struct {
	char   buf[65536];
	size_t len;
	bool   full;      /* set if output did not fit */
} Json;

static void put(Json *j, const char *fmt, ...)
{
	if (j->full)
		return;

	va_list ap;
	va_start(ap, fmt);
	int n = vsnprintf(j->buf + j->len, sizeof j->buf - j->len, fmt, ap);
	va_end(ap);

	if (n < 0 || (size_t)n >= sizeof j->buf - j->len)
		j->full = true;
	else
		j->len += (size_t)n;
}

static void put_str(Json *j, const char *s)
{
	put(j, "\"");
	for (; *s; s++) {
		unsigned char c = (unsigned char)*s;

		if (c == '"' || c == '\\')
			put(j, "\\%c", c);
		else if (c < 0x20)
			put(j, "\\u%04x", c);
		else
			put(j, "%c", c);
	}
	put(j, "\"");
}

/* ------------------------------------------------------------------ */
/* Request body (application/x-www-form-urlencoded)                    */
/* ------------------------------------------------------------------ */

/* Copies the decoded value of `key` into out. Returns false (and an empty
 * string) if the key is missing or the value does not fit. */
static bool form_get(const char *body, const char *key, char *out, size_t cap)
{
	size_t klen = strlen(key);
	const char *p = body;

	out[0] = '\0';

	while (*p) {
		if (strncmp(p, key, klen) == 0 && p[klen] == '=') {
			size_t n = 0;

			for (p += klen + 1; *p && *p != '&'; p++) {
				char c = *p;

				if (c == '+') {
					c = ' ';
				} else if (c == '%' && isxdigit((unsigned char)p[1]) &&
				           isxdigit((unsigned char)p[2])) {
					char hex[3] = { p[1], p[2], 0 };
					c = (char)strtol(hex, NULL, 16);
					p += 2;
				}

				if (n + 1 >= cap) {
					out[0] = '\0';
					return false;
				}
				out[n++] = c;
			}

			out[n] = '\0';
			return true;
		}

		p = strchr(p, '&');
		if (!p)
			break;
		p++;
	}

	return false;
}

/* ------------------------------------------------------------------ */
/* API endpoints. They run with the bot list locked, so they only fill */
/* a buffer; the response is sent after unlocking.                     */
/* ------------------------------------------------------------------ */

static const char *state_name(ConnectionState s)
{
	switch (s) {
	case CONN_DISCONNECTED:        return "Disconnected";
	case CONN_CONNECTING_GATEWAY:  return "Connecting to gateway";
	case CONN_CONNECTED_GATEWAY:   return "Gateway connected";
	case CONN_WAIT_GATEWAY_LOGIN:  return "Waiting for gateway login";
	case CONN_GATEWAY_LOGIN_SUCCESS: return "Gateway login ok";
	case CONN_GATEWAY_LOGIN_FAILED:  return "Gateway login failed";
	case CONN_CONNECTING_GAME:     return "Connecting to game";
	case CONN_CONNECT_GAME:        return "Game connection started";
	case CONN_CONNECTED_GAME:      return "Game connected";
	case CONN_WAIT_GAME_LOGIN:     return "Waiting for game login";
	case CONN_CONNECTED:           return "Connected";
	case CONN_RECONNECTING:        return "Reconnecting";
	case CONN_CLOSED:              return "Closed";
	default:                       return "Unknown";
	}
}

/* GET /api/status
 * {"bots":[{"igg_id":"123","name":"..","device_type":1,"enabled":true,
 *           "state":"Connected","online":true}]}
 * The access key is never sent to the browser. */
static void api_status(BotList *l, Json *j)
{
	put(j, "{\"bots\":[");
	for (size_t i = 0; i < l->count; i++) {
		const Connection *c = l->bot[i];

		put(j, "%s{\"igg_id\":\"%lld\",\"name\":", i ? "," : "", (long long)c->auth.igg_id);
		put_str(j, c->player.name);
		put(j, ",\"device_type\":%u,\"enabled\":%s,\"state\":",
		    (unsigned)c->auth.device_type, c->enabled ? "true" : "false");
		put_str(j, state_name(c->state));
		put(j, ",\"online\":%s}", c->state == CONN_CONNECTED ? "true" : "false");
	}
	put(j, "]}");
}

/* POST /api/add     igg_id, device_uuid, access_key, device_type, admin_name */
static const char *api_add(BotList *l, const char *body)
{
	BotAccount a = {0};
	char type[8];

	form_get(body, "igg_id",      a.igg_id,      sizeof a.igg_id);
	form_get(body, "device_uuid", a.device_uuid, sizeof a.device_uuid);
	form_get(body, "access_key",  a.access_key,  sizeof a.access_key);
	form_get(body, "admin_name",  a.admin_name,  sizeof a.admin_name);
	form_get(body, "device_type", type,          sizeof type);
	a.device_type = atoi(type);

	return BotsAdd(l, &a);
}

/* POST /api/delete  igg_id */
static const char *api_delete(BotList *l, const char *body)
{
	char id[24];
	form_get(body, "igg_id", id, sizeof id);
	return BotsRemove(l, id);
}

/* POST /api/start, /api/stop   igg_id (optional: all bots when missing) */
static const char *api_start_stop(BotList *l, const char *body, bool start)
{
	char id[24];
	const char *which = (form_get(body, "igg_id", id, sizeof id) && id[0]) ? id : NULL;
	return start ? BotsStart(l, which) : BotsStop(l, which);
}

/* Returns the HTTP status; the JSON body is in j. */
static int api(BotList *l, bool post, const char *path, const char *body, Json *j)
{
	const char *err = NULL;

	if (!post && strcmp(path, "/api/status") == 0) {
		api_status(l, j);
		return j->full ? 500 : 200;
	} else if (post && strcmp(path, "/api/add") == 0) {
		err = api_add(l, body);
	} else if (post && strcmp(path, "/api/delete") == 0) {
		err = api_delete(l, body);
	} else if (post && strcmp(path, "/api/start") == 0) {
		err = api_start_stop(l, body, true);
	} else if (post && strcmp(path, "/api/stop") == 0) {
		err = api_start_stop(l, body, false);
	} else {
		return 404;
	}

	if (err)
		put(j, "{\"error\":\"%s\"}", err);   /* messages never contain quotes */
	else
		put(j, "{\"ok\":true}");

	return err ? 400 : 200;
}

/* ------------------------------------------------------------------ */
/* Request routing                                                     */
/* ------------------------------------------------------------------ */

/* Reads the headers and, if there is a Content-Length, the body.
 * *body points into req. Returns false on error or if too large. */
static bool read_request(int fd, char *req, size_t cap, const char **body)
{
	size_t len = 0, need = 0;
	const char *body_start = NULL;

	while (len < cap - 1) {
		ssize_t n = recv(fd, req + len, cap - 1 - len, 0);
		if (n < 0 && errno == EINTR)
			continue;
		if (n <= 0)
			return false;

		len += (size_t)n;
		req[len] = '\0';

		if (!body_start) {
			char *end = strstr(req, "\r\n\r\n");
			if (!end)
				continue;

			body_start = end + 4;

			const char *cl = header(req, "Content-Length");
			size_t body_len = cl ? strtoul(cl, NULL, 10) : 0;

			if (body_len >= cap - (size_t)(body_start - req))
				return false;   /* too large */

			need = (size_t)(body_start - req) + body_len;
		}

		if (len >= need) {
			*body = body_start;
			return true;
		}
	}
	return false;
}

static void respond_json(int fd, int code, const Json *j)
{
	respond(fd, code, code == 200 ? "OK" : code == 400 ? "Bad Request" : "Internal Server Error",
	        "application/json", j->buf, j->len, "");
}

static void handle_client(int fd, WebGuiContext *ctx)
{
	struct timeval tv = { .tv_sec = 5 };
	setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
	setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);

	char req[8192], method[8], path[256];
	const char *body = "";

	if (!read_request(fd, req, sizeof req, &body) ||
	    sscanf(req, "%7s %255s", method, path) != 2) {
		respond_text(fd, 400, "Bad Request");
		return;
	}

	bool post = strcmp(method, "POST") == 0;

	if (!post && strcmp(method, "GET") != 0) {
		respond_text(fd, 405, "Method Not Allowed");
		return;
	}

	if (ctx->auth_enabled && !authorized(req)) {
		respond(fd, 401, "Unauthorized", "text/plain", "Unauthorized", 12,
		        "WWW-Authenticate: Basic realm=\"Lords Mobile Bot\"\r\n");
		return;
	}

	/* The browser resends cached Basic credentials to any site that posts
	 * here. A custom header can only be set by our own page's fetch(), so
	 * requiring it blocks cross-site form posts. */
	if (post && !header(req, "X-Requested-With")) {
		respond_text(fd, 403, "Forbidden");
		return;
	}

	path[strcspn(path, "?")] = '\0';

	if (!post && strcmp(path, "/") == 0) {
		respond(fd, 200, "OK", "text/html; charset=utf-8",
		        webgui_page, sizeof webgui_page, "");
	} else if (strncmp(path, "/api/", 5) == 0) {
		Json j = { .len = 0, .full = false };

		BotsLock(ctx->bots);
		int code = api(ctx->bots, post, path, body, &j);
		BotsUnlock(ctx->bots);   /* never hold the lock while sending */

		if (code == 404)
			respond_text(fd, 404, "Not Found");
		else if (code == 500)
			respond_text(fd, 500, "Internal Server Error");
		else
			respond_json(fd, code, &j);
	} else {
		respond_text(fd, 404, "Not Found");
	}
}

/* ------------------------------------------------------------------ */
/* Server thread                                                       */
/* ------------------------------------------------------------------ */

static void *server_thread(void *arg)
{
	WebGuiContext *ctx = arg;

	while (!stopping) {
		int fd = accept(listen_fd, NULL, NULL);

		if (fd < 0) {
			if (stopping || errno == EBADF || errno == EINVAL)
				break;
			continue;
		}

		handle_client(fd, ctx);
		close(fd);
	}
	return NULL;
}

int WebGuiStart(WebGuiContext *ctx)
{
	if (!ctx || !ctx->bots || !ctx->host[0] || !ctx->port)
		return 0;

	if (ctx->auth_enabled) {
		if (!ctx->password[0]) {
			fprintf(stderr, "Web GUI: auth is enabled but the password is empty\n");
			return 0;
		}

		char creds[200];
		int  n = snprintf(creds, sizeof creds, "%s:%s", ctx->username, ctx->password);

		memcpy(auth_token, "Basic ", 6);
		base64((unsigned char *)creds, (size_t)n, auth_token + 6);
	}

	struct sockaddr_in addr = { .sin_family = AF_INET, .sin_port = htons(ctx->port) };
	if (inet_pton(AF_INET, ctx->host, &addr.sin_addr) != 1) {
		fprintf(stderr, "Web GUI: invalid host '%s'\n", ctx->host);
		return 0;
	}

	listen_fd = socket(AF_INET, SOCK_STREAM, 0);
	if (listen_fd < 0) {
		perror("Web GUI socket");
		return 0;
	}

	int one = 1;
	setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

	if (bind(listen_fd, (struct sockaddr *)&addr, sizeof addr) < 0 ||
	    listen(listen_fd, 8) < 0) {
		perror("Web GUI bind/listen");
		goto fail;
	}

	stopping = 0;
	if (pthread_create(&thread, NULL, server_thread, ctx) != 0)
		goto fail;

	started = true;
	LOGI("Web GUI listening on http://%s:%u/\n", ctx->host, (unsigned)ctx->port);
	return 1;

fail:
	close(listen_fd);
	listen_fd = -1;
	return 0;
}

void WebGuiStop(void)
{
	if (!started)
		return;

	stopping = 1;
	shutdown(listen_fd, SHUT_RDWR);   /* wakes the thread out of accept() */
	pthread_join(thread, NULL);

	close(listen_fd);
	listen_fd = -1;
	started = false;
}
